import { GradumConstrainer } from "../../../../build/gradum-kit.esm";
export class PlaylistConstrainer extends GradumConstrainer {
    constructor() {
        super(...arguments);
        this.keyName = "constrainer";
        this.constrainerName = "playlist";
    }
    testAddingSong(song) {
        return !this.model.songs.find(entry => entry === song.id);
    }
}
