___CSS_LOADER_EXPORT___.push([module.id, `gradum-playlist {
    position: absolute;
}

gradum-playlist > .gradum-rich-element {
    display: flex;
    flex-direction: column;
    gap: var(--gap-tiny);
    align-items: center;
}

gradum-playlist > .gradum-rich-element .gradum-icon {
    width: 56px;
    height: 56px;
    border-radius: var(--radius-small);
    overflow: hidden;
    backdrop-filter: blur(10px);
}

gradum-playlist > .gradum-rich-element > * {
    text-wrap: nowrap;
}

gradum-playlist > .gradum-drawer {
    position: absolute;
    min-width: 300px;
    left: 50%;
    transform: translateX(-50%);
}

gradum-playlist > .gradum-drawer .gradum-drawer-panel {
    padding: var(--gap-medium);
    border-radius: var(--radius-small);

    background-color: var(--surface-2);
    border: 1px solid var(--border);
    height: 300px;

    overflow: auto;
    display: flex;
    flex-direction: column;
    gap: var(--gap-small);
    backdrop-filter: blur(10px);
}

gradum-playlist .empty-playlist-placeholder {
    flex-grow: 1;
    display: flex;
    flex-direction: column;
    gap: var(--gap-medium);

    align-items: center;
    justify-content: center;
    text-align: center;
    padding: var(--gap-medium);
}

gradum-playlist .empty-playlist-placeholder .gradum-icon {
    width: 32px;
    height: 32px;
}

